  "home.hero.cta2": { en: "See How It Works", pcm: "See How E Dey Work", yo: "Wo Bí Ó Ṣe Ń Ṣiṣẹ́", ha: "Duba Yadda Yake", ig: "Hụ Ka Ọ Si Arụ Ọrụ" },
